496 std::optional<bool> KnownBits::ne(const KnownBits &LHS, const KnownBits &RHS) {
497   if (std::optional<bool> KnownEQ = eq(LHS, RHS))
498     return std::optional<bool>(!*KnownEQ);
499   return std::nullopt;
